@Polynomial.hasseDeriv_map : ∀ {R : Type u_1} [inst : Semiring R] {S : Type u_2} [inst_1 : Semiring S] (f : R →+* S)
  (k : ℕ) (p : Polynomial R),
  (Polynomial.hasseDeriv k) (Polynomial.map f p) = Polynomial.map f ((Polynomial.hasseDeriv k) p)

@MvPolynomial.pderiv_map : ∀ {R : Type u_1} {σ : Type u_2} [inst : CommSemiring R] {S : Type u_3}
  [inst_1 : CommSemiring S] {φ : R →+* S} {f : MvPolynomial σ R} {i : σ},
  (MvPolynomial.pderiv i) ((MvPolynomial.map φ) f) = (MvPolynomial.map φ) ((MvPolynomial.pderiv i) f)

@Finsupp.mapRange_smul : ∀ {α : Type u_1} {M : Type u_2} {N : Type u_3} {R : Type u_4} [inst : Zero M]
  [inst_1 : SMulZeroClass R M] [inst_2 : Zero N] [inst_3 : SMulZeroClass R N] {f : M → N} {hf : f 0 = 0} (c : R)
  (v : α →₀ M), (∀ (x : M), f (c • x) = c • f x) → Finsupp.mapRange f hf (c • v) = c • Finsupp.mapRange f hf v

@MvPolynomial.coeff_map : ∀ {R : Type u_1} {S₁ : Type u_2} {σ : Type u_3} [inst : CommSemiring R]
  [inst_1 : CommSemiring S₁] (f : R →+* S₁) (p : MvPolynomial σ R) (m : σ →₀ ℕ),
  ((MvPolynomial.map f) p).coeff m = f (p.coeff m)

@MvPolynomial.coeff_addMonoidAlgebraMap : ∀ {R : Type u_1} {S₁ : Type u_2} {σ : Type u_3} [inst : CommSemiring R]
  [inst_1 : CommSemiring S₁] (g : S₁ →+ R) (φ : MvPolynomial σ S₁) (m : σ →₀ ℕ),
  (AddMonoidAlgebra.map g φ).coeff m = g (φ.coeff m)
